(window.__XDATA=window.__XDATA||{})["plus-xprepade"]={"format":"ri-plus","matiere":"xprepade","nc":[{"a":"0","av":1,"c":0,"q":"La procidence du cordon ombilical peut provoquer une asphyxie périnatale.","t":"vf","nc":1,"why":"La procidence du cordon n'est citée dans aucune source (asphyxie traitée livre p.62-68 sans cette cause)"},{"a":"18","c":0,"q":"Les causes immédiates de la malnutrition incluent l'insécurité alimentaire des ménages.","t":"vf","nc":1,"why":"Classement causes immédiates/sous-jacentes/fondamentales annoncé en objectif (livret p.94) mais non développé dans les sources"},{"a":"18","c":0,"q":"L'absence d'infrastructure sanitaire est une cause fondamentale de la malnutrition.","t":"vf","nc":1,"why":"Causes fondamentales de la malnutrition non développées dans les sources"},{"a":"18","c":0,"q":"La malnutrition peut entraîner une réduction du débit cardiaque.","t":"vf","nc":1,"why":"Conséquence non mentionnée dans les sources"},{"a":"24","c":0,"q":"Tous les enfants grandissent exactement au même rythme.","t":"vf","nc":1,"why":"Les sources donnent des repères moyens mais n'abordent pas la variabilité individuelle"},{"a":"25","c":0,"q":"L'activité physique n'a aucun effet sur le développement physique de l'enfant.","t":"vf","nc":1,"why":"Lien activité physique / développement physique non traité dans les sources"},{"a":"29","c":0,"q":"La dystocie des épaules augmente le risque de paralysie du plexus brachial.","t":"vf","nc":1,"why":"Livre p.107 : paralysie due à une traction forte sur le membre supérieur ; la dystocie des épaules n'est pas nommée"},{"a":"29","c":0,"q":"Les traumatismes obstétricaux n'ont jamais de séquelles.","t":"vf","nc":1,"why":"Livre p.104-108 : formes graves pouvant engager le pronostic vital, mais les séquelles ne sont pas évoquées explicitement"},{"a":"29","c":0,"q":"Une surveillance clinique attentive est nécessaire après un traumatisme obstétrical.","t":"vf","nc":1,"why":"Livre p.108 parle d'examen minutieux à la naissance, pas explicitement de surveillance après traumatisme"},{"a":"32","c":0,"q":"La pédiatrie est la branche spécialisée de la médecine qui s'occupe du développement psychomoteur, de la physiologie normale et des maladies de l'enfant.","t":"vf","nc":1,"why":"Définition de la pédiatrie absente des sources"},{"a":"32","c":0,"q":"La néonatologie est la branche spécialisée de la pédiatrie qui s'occupe du développement psychomoteur, de la physiologie normale et des maladies du fœtus et du nouveau-né.","t":"vf","nc":1,"why":"Définition de la néonatologie absente des sources"},{"a":"33","c":0,"q":"Le trait caractéristique du nouveau-né est l'alimentation.","t":"vf","nc":1,"why":"« Traits caractéristiques » des tranches d'âge absents des sources"},{"a":"34","c":0,"q":"Le trait caractéristique du nourrisson est sa fragilité.","t":"vf","nc":1,"why":"« Traits caractéristiques » des tranches d'âge absents des sources"},{"a":"34","c":0,"q":"L'enfant en âge préscolaire a un âge compris entre 2-5 ans.","t":"vf","nc":1,"why":"Cours p.67 nomme « enfant d'âge scolaire (2-5 ans) » : terme préscolaire absent, formulation non tranchable"},{"a":"34","c":0,"q":"Le trait caractéristique de l'enfant en âge préscolaire est le jeu.","t":"vf","nc":1,"why":"« Traits caractéristiques » des tranches d'âge absents des sources"},{"a":"34","c":0,"q":"L'enfant en âge scolaire a un âge compris entre 6-12 ans.","t":"vf","nc":1,"why":"Cours p.67 : « enfant d'âge scolaire (2-5 ans) » puis « enfant (6-12 ans) » — contradictoire avec l'énoncé, non tranchable"},{"a":"34","c":0,"q":"Le trait caractéristique de l'enfant en âge scolaire est l'apprentissage.","t":"vf","nc":1,"why":"« Traits caractéristiques » des tranches d'âge absents des sources"},{"a":"41","c":0,"q":"La réanimation néonatale est basée sur des gestes en vue de rétablir les fonctions de trois appareils.","t":"vf","nc":1,"why":"Livre p.70-76 : aucune mention de « trois appareils » (trois notions de base seulement)"},{"a":"47","c":0,"q":"Jada, 4 ans, sexe féminin, 16 kg, a une anémie sévère décompensée.","t":"vf","nc":1,"why":"Énoncé de contexte sans affirmation à juger : il sert de situation à la Q68 (corrigée en type cas)"},{"a":"50","c":0,"q":"La première cause d'anémie normocytaire normochrome de l'enfant est le paludisme.","t":"vf","nc":1,"why":"Livre p.178 : « les deux principales causes sont le paludisme et la drépanocytose », sans hiérarchie"},{"a":"53","c":0,"q":"L'âge de plus grand risque de carence en fer chez l'enfant est de 0 à 3 mois.","t":"vf","nc":1,"why":"Âge de plus grand risque de carence en fer non précisé dans les sources"},{"a":"53","c":0,"q":"L'anémie ferriprive chez le nourrisson se manifeste le plus souvent par une splénomégalie massive.","t":"vf","nc":1,"why":"Manifestations de l'anémie ferriprive (splénomégalie) non décrites dans les sources"},{"a":"58","c":0,"q":"La maladie hémorragique du nouveau-né est rare après J10.","t":"vf","nc":1,"why":"Livre p.96-97 : rare entre J8 et J10, et forme tardive possible dans les semaines ; rien sur « après J10 »"},{"a":"60","c":0,"q":"La maladie hémorragique du nouveau-né est favorisée par ces éléments suivants : allaitement exclusif, accouchement non eutocique et être africain noir.","t":"vf","nc":1,"why":"Livre p.96 cite race noire et accouchement dystocique, mais pas l'allaitement exclusif"},{"a":"60","c":0,"q":"Le défaut d'apport en facteurs II, VII, IX et X concourt à une insuffisance de la coagulation entraînant de facto une maladie hémorragique du nouveau-né.","t":"vf","nc":1,"why":"Livre p.96-98 : carence en vitamine K1 et facteurs vit. K-dépendants ; « défaut d'apport en facteurs » non tranchable"},{"a":"62","c":0,"q":"Le dosage des facteurs II, VII, IX, X et celui de la vit K constituent l'examen essentiel dans la recherche des éléments concourant à la maladie hémorragique du NN.","t":"vf","nc":1,"why":"Livre p.98 désigne le temps de Quick comme examen clé ; le dosage des facteurs n'est pas évoqué, formulation non tranchable"},{"a":"63","c":0,"q":"La prévention de la maladie hémorragique du NN se résume à l'administration de la vit K à la naissance par voie IM.","t":"vf","nc":1,"why":"Livre ambigu : conclusion p.102 « la prévention repose sur la vit K1 IM » mais p.100 ajoute des mesures pendant la grossesse"},{"a":"64","c":0,"q":"Avant la photothérapie, il faut mettre l'enfant nu et protéger les organes génitaux de la fille avec une couche.","t":"vf","nc":1,"why":"Livret p.14 (photo) : génitaux du garçon ; livre p.93 : génitaux du nouveau-né sans distinction ; OCR p.14 sans ce passage"},{"a":"66","c":0,"q":"L'hyperactivité est l'accident auquel est exposé l'enfant sous photothérapie.","t":"vf","nc":1,"why":"Livret p.16 (photo) cite l'hyperactivité parmi plusieurs incidents ; « l'accident » au singulier non tranchable, passage absent de l'OCR"},{"a":"77","c":0,"q":"YK, infirmier, prend des dispositions pour les soins de photothérapie mais ne porte pas de cache-nez.","t":"vf","nc":1,"why":"Port du cache-nez non mentionné pour la photothérapie (livret p.12-17)"},{"a":"83","c":0,"q":"Avant les soins l'agent de santé doit se frictionner les mains avec la solution hydro-alcoolique.","t":"open","nc":1,"why":"Livret p.16 : la technique commence par « se laver les mains à l'eau et au savon », puis les essuyer OU se frictionner avec la SHA ; formulation « doit se frictionner » non tranchable."},{"a":"84","c":0,"q":"La photothérapie peut provoquer des lésions oculaires à type de kératite.","t":"open","nc":1,"why":"Le livret p.17 (photo) cite bien « Lésions oculaires : (kératite ; rétinopathie) » parmi les incidents, mais l'OCR de cette ligne est illisible : aucun snip vérifiable (réponse attendue : Vrai)."},{"a":"93","c":0,"q":"Le nouveau-né macrosome est un nouveau-né à risque.","t":"open","nc":1,"why":"Aucune source ne classe explicitement le macrosome comme « nouveau-né à risque » (livret p.129 le définit sans le qualifier ; le livre ne le dit que pour le nouveau-né de mère diabétique)."},{"a":"93","c":0,"q":"L'agent pathogène du tétanos s'appelle le Clostridium tétanie.","t":"open","nc":1,"why":"Sujet absent des sources (germe du tétanos jamais nommé)."},{"a":"93","c":0,"q":"La porte d'entrée du germe du tétanos est essentiellement ombilicale.","t":"open","nc":1,"why":"Le cours (p.19, 39) évoque le tétanos néonatal / ombilical lié au cordon, mais ne dit pas que la porte d'entrée est « essentiellement » ombilicale."},{"a":"93","c":0,"q":"Les crises paroxystiques sont des signes cliniques exagérés sous l'effet de la lumière.","t":"open","nc":1,"why":"Sujet absent des sources (clinique du tétanos non traitée)."},{"a":"114","c":0,"q":"La prévalence de l'asthme en Côte d'Ivoire est la même partout dans le monde, soit environ 1,4 %.","t":"open","nc":1,"why":"Aucun chiffre de prévalence (1,4 %) dans les sources ; le livre p.247 donne seulement fréquence, âge et létalité."},{"a":"126","c":0,"q":"Entre 0 et 3 mois, le bébé peut étendre ses membres sans difficulté.","t":"open","nc":1,"why":"Les jalons 1-3 mois du livret (p.144-145) ne parlent pas de l'extension des membres."},{"a":"127","c":0,"q":"La tête du bébé vacille jusqu'à 3 mois, après quoi elle reste plus droite.","t":"open","nc":1,"why":"Le livret (p.145) indique seulement « 3 mois : maintien de la tête » ; le fait que la tête « vacille » avant n'est pas écrit."},{"a":"127","c":0,"q":"Entre 0 et 3 mois, le bébé peut se tenir sur ses avant-bras et redresser légèrement la tête.","t":"open","nc":1,"why":"Appui sur les avant-bras absent des jalons du livret (p.144-145)."},{"a":"129","c":0,"q":"Faux. Il tourne sa tête vers les sons. (ligne « Réponse 171 », corrigé de Q170)","t":"open","nc":1,"why":"Ligne de réponse et non question ; de plus le livret ne situe « tourne la tête pour regarder une personne qui l'appelle » qu'à 4-5 mois (p.145), pas avant 3 mois."},{"a":"129","c":0,"q":"Entre 0 et 3 mois, bébé reconnaît les sons familiers et la voix de ses parents.","t":"open","nc":1,"why":"Le livret (p.145) dit « reconnaît le visage de sa mère » et « réagit aux stimuli sonores » à 3 mois ; la reconnaissance de la voix des parents n'est pas écrite."},{"a":"131","c":0,"q":"Entre 4 et 6 mois, le bébé commence à s'asseoir maintenu par les mains.","t":"open","nc":1,"why":"Le livret (p.145) dit « 4-5 mois : tenu assis tête droite » et « 6 mois : station assise », sans préciser « maintenu par les mains » ; non tranchable."},{"a":"132","c":0,"q":"Entre 4 et 6 mois, le bébé comprend des phrases complexes.","t":"open","nc":1,"why":"Compréhension du langage à 4-6 mois non décrite dans le livret (seulement « réagit à l'appel de son nom » à 6 mois)."},{"a":"132","c":0,"q":"Le bébé de 4 à 6 mois imite les gestes et les sons faits par les adultes.","t":"open","nc":1,"why":"Imitation des gestes non citée ; « répétition des sons » est située à 6-8 mois dans le livret (p.145) ; non tranchable."},{"a":"132","c":0,"q":"Entre 7 et 9 mois, le bébé reste assis sans soutien.","t":"open","nc":1,"why":"Le livret (p.145) indique « 6 mois : station assise » sans préciser « sans soutien » ni la tranche 7-9 mois."},{"a":"132","c":0,"q":"À 9 mois, le bébé se déplace à quatre pattes de manière très fluide et rapide.","t":"open","nc":1,"why":"Le livret (p.145) situe la marche à 4 pattes à 6-8 mois mais ne dit rien de sa fluidité ou rapidité à 9 mois."},{"a":"132","c":0,"q":"Le bébé de 7 à 9 mois connaît son nom et comprend le sens du « non ».","t":"open","nc":1,"why":"Le livret place « réagit à l'appel de son nom » à 6 mois et « comprend les interdits » à 10-12 mois (p.145-146) ; non tranchable pour 7-9 mois."},{"a":"134","c":0,"q":"Mettre le nouveau-né sous une lampe chauffante ou sur une table radiante pour ne pas qu'il prenne froid est l'une des précautions à prendre avant de l'examiner.","t":"open","nc":1,"why":"Le cours (p.12) demande d'examiner « sans le refroidir » mais ne cite ni lampe chauffante ni table radiante comme précaution d'examen."},{"a":"138","c":0,"q":"Accompagner le nouveau-né chez la puéricultrice est un soin délégué.","t":"open","nc":1,"why":"Le livre p.313 définit soins délégués / propres / en collaboration (accompagner un malade à la radio = collaboration) mais ne traite pas ce cas précis."},{"a":"141","c":0,"q":"Les vomissements sont un rejet actif du contenu liquide de l'estomac, faisant intervenir des contractions abdominales et diaphragmatiques.","t":"open","nc":1,"why":"Le livre (p.184) parle du rejet « d'une partie du contenu de l'estomac » sans le limiter au liquide (l'aspect peut être alimentaire) ; variante de Q192 non tranchable."},{"a":"142","c":0,"q":"Lors de l'interrogatoire d'un enfant vomissant, l'infirmier doit rechercher :","t":"open","nc":1,"why":"Amorce sans affirmation à juger ; ses items sont les Q196 et Q197."},{"a":"143","c":0,"q":"Lors de l'interrogatoire d'un enfant vomissant, l'infirmier doit rechercher un antécédent de prématurité et le score d'Apgar à la naissance.","t":"open","nc":1,"why":"Les antécédents à rechercher listés par le livre (p.186-187) ne mentionnent ni prématurité ni score d'Apgar ; non établi."},{"a":"143","c":0,"q":"Concernant la sténose hypertrophique du pylore (SHP) :","t":"open","nc":1,"why":"Amorce sans affirmation à juger (items Q199-Q200)."},{"a":"143","c":0,"q":"(SHP) Elle se manifeste typiquement chez un nourrisson de 2 à 8 semaines par des vomissements en jet, non bilieux, survenant après la tétée.","t":"open","nc":1,"why":"Le livre (p.188) cite seulement la SHP comme cause de vomissements, sans sa clinique."},{"a":"143","c":0,"q":"(SHP) Le bilan biologique retrouve classiquement une acidose métabolique hyperchlorémique.","t":"open","nc":1,"why":"Biologie de la SHP absente des sources."},{"a":"143","c":0,"q":"Devant un enfant présentant des vomissements et une altération de l'état général : l'odeur acétonique de l'haleine et une polyurie associée doivent faire évoquer un syndrome occlusif.","t":"open","nc":1,"why":"Sujet absent des sources."},{"a":"143","c":0,"q":"La présence d'une raideur de la nuque et d'une fontanelle tendue chez le nourrisson doit faire évoquer une méningite.","t":"open","nc":1,"why":"Le livre (p.293) cite le bombement de la fontanelle dans la physiopathologie, mais p.295 dit qu'il n'existe pas de signes cliniques spécifiques chez le nourrisson ; non tranchable."},{"a":"143","c":0,"q":"Concernant la prise en charge de la déshydratation par vomissements : la réhydratation orale par SRO est contre-indiquée en cas de vomissements, car elle majore les nausées.","t":"open","nc":1,"why":"SRO et vomissements non traités dans les sources (le livre p.199-201 ne traite la réhydratation que pour la diarrhée)."},{"a":"143","c":0,"q":"La réhydratation intraveineuse est indiquée en cas de signes de déshydratation sévère ou de vomissements incoercibles.","t":"open","nc":1,"why":"Le livre (p.199-201) indique la voie parentérale pour la déshydratation sévère (diarrhée) mais ne parle pas des vomissements incoercibles ; non entièrement établi."},{"a":"143","c":0,"q":"Le SRO doit être administré en très petites quantités et de manière fractionnée (ex : cuillère à café toutes les 5 minutes).","t":"open","nc":1,"why":"Modalité absente des sources."},{"a":"143","c":0,"q":"Concernant l'invagination intestinale aiguë (IIA) :","t":"open","nc":1,"why":"Amorce sans affirmation à juger (items Q207-Q208)."},{"a":"143","c":0,"q":"(IIA) Elle survient typiquement chez le nourrisson entre 3 et 36 mois et se manifeste par des douleurs paroxystiques avec des épisodes de pâleur et de refus alimentaire.","t":"open","nc":1,"why":"Le livre (p.188) cite seulement l'IIA comme cause de vomissements aigus, sans sa clinique."},{"a":"143","c":0,"q":"La présence de selles « gelée de groseille » (mélangées de sang) est un signe constant et précoce de l'IIA.","t":"open","nc":1,"why":"Clinique de l'IIA absente des sources."},{"a":"143","c":0,"q":"Concernant les médicaments antiémétiques chez l'enfant :","t":"open","nc":1,"why":"Amorce sans affirmation à juger (items Q210-Q211)."},{"a":"143","c":0,"q":"Le métoclopramide (Primpéran) peut être administré à domicile systématiquement par les parents dès les premiers vomissements.","t":"open","nc":1,"why":"Le métoclopramide n'est pas cité ; le livre (p.190) nomme métopimazine et alizapride et signale le risque de syndrome extrapyramidal, sans traiter ce cas."},{"a":"143","c":0,"q":"L'ondansétron est un antiémétique de référence, notamment dans les vomissements post-opératoires ou post-chimiothérapie, utilisable chez l'enfant à partir de 6 mois.","t":"open","nc":1,"why":"Ondansétron absent des sources."},{"a":"143","c":0,"q":"Dans les conseils éducatifs donnés aux parents d'un enfant vomissant : il est conseillé de proposer à l'enfant des boissons sucrées type sodas ou jus de fruits pour compenser les pertes d'énergie.","t":"open","nc":1,"why":"Non traité pour l'enfant vomissant (le livre p.200 cite le « coca cola battus » comme solution de réhydratation dans la diarrhée, ce qui ne tranche pas)."},{"a":"143","c":0,"q":"Il faut consulter en urgence si l'enfant présente une fontanelle déprimée, une sécheresse buccale et moins de 5 couches mouillées par jour.","t":"open","nc":1,"why":"Critère des « 5 couches mouillées » et consigne absents des sources."},{"a":"143","c":0,"q":"Concernant les vomissements d'origine chirurgicale : la malrotation intestinale avec volvulus se manifeste chez le nouveau-né par des vomissements bilieux (verts) et constitue une urgence chirurgicale absolue.","t":"open","nc":1,"why":"Malrotation/volvulus absents des sources."},{"a":"143","c":0,"q":"L'appendicite aiguë chez l'enfant se manifeste toujours par des vomissements avant l'apparition des douleurs abdominales.","t":"open","nc":1,"why":"Le livre (p.188) cite seulement l'appendicite comme cause de vomissements aigus fébriles, sans chronologie des signes."},{"a":"143","c":0,"q":"Concernant l'éducation thérapeutique sur les vomissements chroniques :","t":"open","nc":1,"why":"Énoncé incomplet dans le recueil (aucune affirmation après les deux-points)"},{"a":"143","c":0,"q":"Dans le cadre d'une allergie aux protéines du lait de vache (APLV), l'éviction totale du lait de vache et de ses dérivés est le traitement de base.","t":"vf","nc":1,"why":"APLV non traitée dans les sources"},{"a":"143","c":0,"q":"Les régurgitations du nourrisson liées à un RGO (reflux gastro-œsophagien) nécessitent systématiquement une chirurgie (fundoplicature).","t":"vf","nc":1,"why":"Le livre (p. 190) ne cite que l'épaississement des repas pour le RGO ; la chirurgie n'est pas évoquée"},{"a":"18","c":0,"q":"Les causes immédiates de la malnutrition incluent l'insécurité alimentaire des ménages.","t":"vf","nc":1,"why":"Classement des causes (immédiates/sous-jacentes/fondamentales) annoncé dans les objectifs du livret (p. 94) mais absent des pages fournies"},{"a":"18","c":0,"q":"L'absence d'infrastructure sanitaire est une cause fondamentale de la malnutrition.","t":"vf","nc":1,"why":"Classement des causes absent des sources"},{"a":"18","c":0,"q":"La malnutrition peut entraîner une réduction du débit cardiaque.","t":"vf","nc":1,"why":"Conséquence non mentionnée dans les sources"},{"a":"163","c":0,"q":"L'extraction manuelle est plus sûre et comporte plus risque d'infection que l'extraction par pompe","t":"vf","nc":1,"why":"Aucune comparaison de sécurité/risque infectieux entre extraction manuelle et tire-lait dans le cours (p. 87-88)"},{"a":"162","c":0,"q":"Le soutien psychologique de la mère allaitante est un facteur favorisant la monté laiteuse lors de l'allaitement.","t":"vf","nc":1,"why":"Le cours (p. 88-89) ne le cite pas parmi les facteurs favorisant la montée laiteuse ; le livre (p. 146) cite le manque de soutien comme facteur de déclin de l'allaitement, sans lien explicite avec la montée laiteuse"},{"a":"162","c":0,"q":"A la naissance, l'enfant pèse en moyenne 3 kg et 3,5 kg.","t":"vf","nc":1,"why":"Le cours (p. 67) donne une moyenne de 3 kg ; la formulation « 3 kg et 3,5 kg » n'est pas tranchable"},{"a":"162","c":0,"q":"Les déshydratations aiguës graves peuvent occasionner la fièvre.","t":"vf","nc":1,"why":"Le livre (p. 162, 165) présente la déshydratation comme complication de la fièvre, pas comme sa cause"},{"a":"166","c":0,"q":"La diarrhée de l'enfant nourri au sein se corrige avec ou sans traitement.","t":"vf","nc":1,"why":"Sujet absent des sources"},{"a":"174","c":0,"q":"Quelle est l'une des causes immédiates de la malnutrition ?","t":"qcm","nc":1,"o":["L'insécurité alimentaire des ménages.","L'absence d'infrastructure sanitaire.","Une ration alimentaire inadéquate.","La pauvreté."],"why":"Classement des causes absent des sources"},{"a":"174","c":0,"q":"La difficulté d'accès à une terre fertile est une cause de malnutrition de type :","t":"qcm","nc":1,"o":["Immédiate.","Sous-jacente.","Fondamentale.","Directe."],"why":"Classement des causes absent des sources"},{"a":"177","c":0,"q":"Quel est l'objectif général de ce cours ?","t":"qcm","nc":1,"o":["Décrire les signes cliniques du marasme et du kwashiorkor.","Faire acquérir des connaissances sur la malnutrition chez l'enfant.","Expliquer les causes de la malnutrition.","Décrire le traitement des différents types de malnutrition aiguë."],"why":"Objectif général du livret (p. 94) : « prendre en charge la malnutrition chez l'enfant » ; aucune option ne le reprend (a, c, d sont des objectifs spécifiques)"},{"a":"179","c":0,"q":"La malnutrition est la conséquence directe de la pauvreté et de l'injustice. Ceci est une cause de type :","t":"qcm","nc":1,"o":["Immédiate.","Sous-jacente.","Fondamentale.","Éducationnelle."],"why":"Classement des causes absent des sources"},{"a":"180","c":0,"q":"La réduction du métabolisme d'environ 30% est une conséquence de la malnutrition sur :","t":"qcm","nc":1,"o":["Le plan socio-économique.","Le plan éducationnel.","La santé de l'enfant.","L'environnement socio-sanitaire."],"why":"Conséquences par plan et chiffre de 30 % absents des sources"},{"a":"186","c":0,"q":"L'anorexie du nourrisson nécessite une évaluation médicale surtout lorsque","t":"qcm","nc":1,"o":["Le nourrisson grandit normalement","Il existe une perte de poids ou un ralentissement de la croissance","Il mange occasionnellement moins","Il dort après les repas"],"why":"Le livre (p. 255-258) ne précise pas quand une évaluation médicale s'impose (seulement : rechercher des signes de maladie organique, référer l'anorexie compliquée)"},{"a":"187","c":0,"q":"Parmi les facteurs de risque d'asphyxie périnatale, on retrouve :","t":"qcm","nc":1,"o":["Le décollement placentaire","L'hypertension artérielle maternelle","La procidence du cordon ombilical","Toutes les réponses ci-dessus"],"why":"Le livre (p.70-71) liste les situations à risque de souffrance cérébrale (prématurité, macrosomie, infection, toxémie gravidique, manœuvres…) mais ni le décollement placentaire ni la procidence du cordon"},{"a":"188","c":0,"q":"La complication neurologique majeure de l'asphyxie périnatale est :","t":"qcm","nc":1,"o":["L'encéphalopathie hypoxo-ischémique","La conjonctivite néonatale","L'ictère physiologique","La hernie ombilicale"],"why":"Le terme « encéphalopathie hypoxo-ischémique » est absent des sources ; le livre (p.62) parle seulement de « souffrance cérébrale »"},{"a":"191","c":0,"q":"Quelle est la principale hormone impliquée dans la croissance de l'enfant ?","t":"qcm","nc":1,"o":["L'insuline","L'hormone de croissance (GH)","L'adrénaline","La prolactine"],"why":"L'hormone de croissance n'est mentionnée dans aucune source"},{"a":"194","c":0,"q":"La paralysie du plexus brachial est généralement associée à :","t":"qcm","nc":1,"o":["Une dystocie des épaules","Une prématurité","Une infection néonatale","Un ictère physiologique"],"why":"Le livre (p.107) l'attribue à une traction forte sur le membre supérieur pour dégager la tête ; la « dystocie des épaules » n'est pas citée"},{"a":"205","c":0,"q":"La néonatologie est la branche spécialisée de la pédiatrie consacrée :","t":"qcm","nc":1,"o":["Au fœtus et au nouveau-né","Au fœtus et à la petite enfance","Au fœtus et au nourrisson"],"why":"La néonatologie n'est définie dans aucune source"},{"a":"206","c":0,"q":"Le trait caractéristique du nourrisson est :","t":"qcm","nc":1,"o":["L'alimentation","Le sommeil","Le jeu"],"why":"Aucune source ne définit le « trait caractéristique » des tranches d'âge"},{"a":"207","c":0,"q":"Le trait caractéristique de l'adolescent est :","t":"qcm","nc":1,"o":["Son attachement à ses parents","Le conflit avec la société","Son projet"],"why":"Aucune source ne définit le « trait caractéristique » de l'adolescent"},{"a":"207","c":0,"q":"L'enfant âgé de 6-12 ans est caractérisé par :","t":"qcm","nc":1,"o":["L'apprentissage","Le sport","Les promenades"],"why":"Aucune source ne définit le trait caractéristique de l'enfant de 6-12 ans"},{"a":"207","c":0,"q":"Voici une liste de besoins : 1-alimentation ; 2-sommeil ; 3-croissance ; 4-travail ; 5-développement psychomoteur ; 6-protection ; 7-éducation. Relever la combinaison qui correspond aux principaux besoins de l'enfant en bonne santé.","t":"qcm","nc":1,"o":["(1;2;3;4;5)","(2;3;4;5;7)","(1;3;5;6;7)"],"why":"Cette liste des principaux besoins de l'enfant sain ne figure dans aucune source (le livret p.150-152 cite sommeil, activités, hygiène, environnement)"},{"a":"208","c":0,"q":"Parmi les principales pathologies rencontrées chez l'adolescent, il y a un intrus : cochez-le.","t":"qcm","nc":1,"o":["Paludisme","Drépanocytose","Infection bactérienne"],"why":"Les pathologies de l'adolescent ne sont traitées dans aucune source"},{"a":"208","c":0,"q":"Le groupe d'enfants dont le trait caractéristique est la fragilité a un âge compris entre :","t":"qcm","nc":1,"o":["1-23 mois","2-5 ans","0-28 jours"],"why":"Le cours (p.24) évoque « la fragilité du nouveau-né » mais ne la présente pas comme trait caractéristique d'une tranche d'âge"},{"a":"213","c":0,"q":"Cocher parmi les propositions suivantes les deux gestes à faire en salle de naissance lorsque le bébé pleure et respire normalement.","t":"qcm","nc":1,"o":["Déposer le bébé sur un linge sec sur le ventre de la mère","Stimuler le bébé en frottant son dos avec la main","Essuyer le bébé avec un linge sec en prenant soin de ne pas enlever le vernix caseosa","Aspirer les sécrétions dans la bouche du bébé","Maintenir le nouveau-né dans le linge mouillé"],"why":"Sources divergentes : le cours (p.7) dit sécher + peau à peau sur le ventre de la mère (A, C), le livre (p.74) dit aspirer + essuyer (C, D)"},{"a":"214","c":0,"q":"Cocher parmi les propositions suivantes les deux gestes à faire en salle de naissance lorsque le bébé ne pleure pas et ne respire pas.","t":"qcm","nc":1,"o":["Aspirer les sécrétions dans la bouche du bébé","Forte friction de la peau du bébé après y avoir déposé de l'alcool à 60° voire 90°","Stimuler le bébé en frottant son dos avec la main","Taper vigoureusement sur les fesses, plantes des pieds","Pincer le mamelon du nouveau-né pour lui arracher des cris"],"why":"Le livre (p.74-75) confirme « aspirer » et proscrit B, D, E, mais la stimulation par frottement du dos n'est mentionnée nulle part"},{"a":"219","c":0,"q":"Parmi les facteurs à risque de souffrance cérébrale suivants, relever celui qui est lié au fœtus :","t":"qcm","nc":1,"o":["Consommation de substances toxiques pendant la grossesse","La post maturité","L'accouchement dystocique"],"why":"Le livre p.70 cite comme facteurs liés au fœtus la prématurité, la macrosomie, l'infection, l'hypotrophie, la malformation : aucune des options n'y figure"},{"a":"220","c":0,"q":"Pour décider de la réanimation d'un nouveau-né en salle de naissance, l'agent de santé se pose 3 questions ; parmi les questions suivantes, relever celle qui n'est pas nécessaire :","t":"qcm","nc":1,"o":["Le bébé est-il à terme ?","Le bébé a un bon tonus ?","Quel est son score d'APGAR ?"],"why":"Les 3 questions de décision ne figurent pas dans les sources (le livre p.74 base la conduite sur la vitalité/Apgar)"},{"a":"220","c":0,"q":"Parmi les éléments suivants, lequel permet à l'agent de santé de mettre en route des gestes de réanimation néonatale ?","t":"qcm","nc":1,"o":["Le bébé tousse","Le bébé ne respire pas","Le bébé est agité"],"why":"Les critères de déclenchement de la réanimation (« ne respire pas ») ne sont pas énoncés dans les sources"},{"a":"220","c":0,"q":"La réanimation néonatale en salle de naissance est un acte qui ne s'improvise pas ; cela signifie que :","t":"qcm","nc":1,"o":["Le matériel de réanimation est réuni rapidement juste après la naissance du bébé","Le matériel de réanimation est demandé par la sage-femme selon les besoins du bébé","Tout le matériel de réanimation est réuni avant la naissance du bébé"],"why":"Le livre (p.72, 76) parle de vérification du matériel et dit que l'improvisation n'a pas sa place, sans préciser que le matériel est réuni avant la naissance"},{"a":"223","c":0,"q":"Quel est l'âge de plus grand risque de carence en fer chez l'enfant ?","t":"qcm","nc":1,"o":["De 0 à 3 mois","De 6 à 24 mois","De 4 à 6 ans"],"why":"L'âge de plus grand risque de carence en fer n'est indiqué dans aucune source"},{"a":"224","c":0,"q":"Relever deux des facteurs de risque de carence en fer chez le nourrisson.","t":"qcm","nc":1,"o":["Prématurité","Allaitement maternel exclusif prolongé sans supplémentation après 6 mois","Consommation excessive de lait de vache avant 12 mois","Post maturité"],"why":"Les sources donnent des facteurs de l'anémie en général (prématurité, substituts du lait, erreurs de diversification, p.176) mais pas de la carence en fer ; options 2 et 3 non tranchables"},{"a":"224","c":0,"q":"Le diagnostic de certitude de l'anémie ferriprive repose sur :","t":"qcm","nc":1,"o":["La baisse de l'hémoglobine seule","La baisse du fer sérique et l'augmentation de la capacité totale de fixation","La baisse de la ferritine"],"why":"Le livre (p.180) cite le dosage du fer sérique et de la capacité totale de fixation parmi les examens, sans dire ce qui fait le diagnostic de certitude"},{"a":"226","c":0,"q":"L'anémie hémolytique auto-immune chez l'enfant est caractérisée par :","t":"qcm","nc":1,"o":["Un test de Coombs direct positif","Un test de Coombs direct négatif","Un volume globulaire moyen (VGM) très bas"],"why":"Le test de Coombs dans l'anémie hémolytique auto-immune n'est pas traité dans les sources"},{"a":"228","c":0,"q":"La carence en folate (vitamine B9) chez l'enfant est favorisée par :","t":"qcm","nc":1,"o":["Une alimentation riche en légumes verts","Une carence d'apport chez le nourrisson ou certaines maladies de malabsorption","Un excès de viande rouge"],"why":"Les causes de la carence en folates ne sont pas décrites dans les sources"},{"a":"229","c":0,"q":"La première cause d'anémie aiguë de l'enfant de moins de 5 ans en Côte d'Ivoire est :","t":"qcm","nc":1,"o":["La carence en fer","La pneumonie","Le paludisme grave"],"why":"Le livre (p.176) dit que les causes sont dominées par le paludisme grave ET la carence martiale, sans désigner la première"},{"a":"230","c":0,"q":"Le traitement de l'anémie sévère post-palustre chez l'enfant repose sur :","t":"qcm","nc":1,"o":["La transfusion sanguine selon les critères OMS (Hb < 4-5 g/dl ou signe de décompensation)","Le fer systématique","Les corticoïdes"],"why":"Le livre (p.182-183) décrit la transfusion de l'anémie sévère mais pas les critères OMS (Hb < 4-5 g/dl) cités"},{"a":"236","c":0,"q":"Pour confirmer le diagnostic de la maladie hémorragique du nouveau-né, je collabore avec le médecin pour la réalisation de :","t":"qcm","nc":1,"o":["Fibrinogène","TP/TCK","Protéine C réactive (CRP)"],"why":"Le livre (p.98) ne cite que le « temps de Quick » ; ni TP ni TCK ne sont nommés, l'équivalence n'est pas donnée par les sources"},{"a":"237","c":0,"q":"Pour confirmer le diagnostic de la maladie hémorragique du nouveau-né, je collabore avec le médecin pour la réalisation d'un des examens suivants :","t":"qcm","nc":1,"o":["Protéine C réactive (CRP)","Groupe sanguin/Rhésus","Taux de prothrombine"],"why":"Le livre (p.98) ne cite que le « temps de Quick » ; le taux de prothrombine n'est pas nommé dans les sources"},{"a":"241","c":0,"q":"La vitamine K1 appartient à la classe thérapeutique des :","t":"qcm","nc":1,"o":["Hémostatiques","Antibiotiques","Anticonvulsivants"],"why":"La classe thérapeutique de la vitamine K1 n'est indiquée dans aucune source"},{"a":"246","c":0,"q":"Joli bébé présente les signes ci-dessous. Parmi ses signes, relever celui qui est en faveur de la forme classique de la maladie hémorragique du nouveau-né","t":"qcm","nc":1,"o":["Hémoptysie","Hématurie","Rectorragie"],"why":"Le livre (p. 97) cite hématurie et rectorragies parmi les saignements, mais ne parle pas de « forme classique » : non tranchable"},{"a":"247","c":0,"q":"CS, infirmier doit faire les soins de photothérapie. Parmi les propositions suivantes relatives aux dispositions à prendre se trouve un intrus. Cochez l'intrus.","t":"qcm","nc":1,"o":["Eviter de porter du parfum","Avoir coupés les ongles, courts et non vernis","Se faire aider par les parents"],"why":"Le chapitre photothérapie du livret (p. 12-17) ne liste pas les dispositions de l'agent de santé ; elles ne figurent que dans d'autres soins"},{"a":"270","c":0,"q":"La bilirubine libre est aussi appelée :","t":"qcm","nc":1,"o":["Bilirubine directe","Bilirubine conjuguée","Bilirubine non conjuguée"],"why":"Aucune source n'énonce explicitement que bilirubine libre = bilirubine non conjuguée (livret p. 12 et livre p. 88 seulement implicites)"},{"a":"281","c":0,"q":"Le nouveau-né qui souffre d'une infection bactérienne présente les signes suivants sauf deux, lesquels ?","t":"qcm","nc":1,"o":["Un état de somnolence ou léthargie","Une hypotonie ou hypertonie","Les réflexes archaïques sont présents","Une bradycardie","Un bombement de la fontanelle antérieure en cas de méningite"],"why":"Livre p. 80 : somnolence, hypotonie/hypertonie, tachycardie > 180/min (donc bradycardie = intrus) ; mais la suite des signes (réflexes archaïques, fontanelle) est sur la p. 81, illisible (photo floue, OCR vide) : le second intrus n'est pas vérifiable"},{"a":"288","c":0,"q":"Le tétanos néonatal est une infection de la plaie ombilicale ou de toute autre porte d'entrée par :","t":"qcm","nc":1,"o":["Le bacille de Koch","Salmonella colis","Le bacille de Périer","Le bacille de Nicolaier"],"why":"Agent du tétanos non décrit dans les sources (le tétanos néonatal n'y est cité qu'en lien avec le cordon et la vaccination)"},{"a":"289","c":0,"q":"L'agent pathogène du tétanos agit sur :","t":"qcm","nc":1,"o":["Les nerfs","Les muscles","Le sang","Le cerveau"],"why":"Physiopathologie du tétanos absente des sources"},{"a":"290","c":0,"q":"Chez le nouveau-né atteint du tétanos, le trismus est une contracture des muscles :","t":"qcm","nc":1,"o":["Des membres","De l'abdomen","De la mâchoire","Toutes les réponses sont justes"],"why":"Trismus / clinique du tétanos absents des sources"},{"a":"290","c":0,"q":"Dans le tétanos néonatal, le trismus est :","t":"qcm","nc":1,"o":["Réductible","Permanent","Irréductible","Douloureux","Irrégulier","Intermittent"],"why":"Trismus / clinique du tétanos absents des sources"},{"a":"290","c":0,"q":"Dans la crise paroxystique du tétanos néonatal, le nouveau-né se met en opisthotonos. Lesquelles des propositions suivantes sont les signes de l'opisthotonos ?","t":"qcm","nc":1,"o":["Les membres inférieurs en hyperextension","Les membres inférieurs en hyperflexion","Les membres supérieurs en hyperextension","Les membres supérieurs en hyperflexion","La tête rejetée en arrière","La tête rejetée en avant"],"why":"Opisthotonos seulement cité (livret p. 15, photothérapie) sans description ; tétanos non traité dans les sources"},{"a":"290","c":0,"q":"Parmi les propositions suivantes, cochez celles que l'on pourrait confondre avec le tétanos du nouveau-né :","t":"qcm","nc":1,"o":["Une méningite","Un paludisme grave","Une crise d'épilepsie","Une tétanie","Une hémorragie cérébro-méningée","Une hypercalcémie"],"why":"Diagnostic différentiel du tétanos néonatal absent des sources"},{"a":"290","c":0,"q":"Parmi les éléments cités ci-dessous, indiquez les complications du tétanos néonatal :","t":"qcm","nc":1,"o":["Infection pulmonaire","Retard mental","Fracture des côtes","Fonte musculaire","Paralysie","Déformation thoracique"],"why":"Complications du tétanos néonatal absentes des sources"},{"a":"174","c":0,"q":"Quelle est l'une des causes immédiates de la malnutrition ?","t":"qcm","nc":1,"o":["L'insécurité alimentaire des ménages.","L'absence d'infrastructure sanitaire.","Une ration alimentaire inadéquate.","La pauvreté."],"why":"Le livret annonce (objectif p. 94) le classement des causes en immédiates/sous-jacentes/fondamentales mais ce chapitre ne figure pas dans les pages fournies ; le livre (p. 261-262) liste des facteurs sans ce classement"},{"a":"174","c":0,"q":"La difficulté d'accès à une terre fertile est une cause de malnutrition de type :","t":"qcm","nc":1,"o":["Immédiate.","Sous-jacente.","Fondamentale.","Directe."],"why":"Classement des causes (immédiates/sous-jacentes/fondamentales) absent des pages fournies ; « terre fertile » introuvable"},{"a":"177","c":0,"q":"Quel est l'objectif général de ce cours ?","t":"qcm","nc":1,"o":["Décrire les signes cliniques du marasme et du kwashiorkor.","Faire acquérir des connaissances sur la malnutrition chez l'enfant.","Expliquer les causes de la malnutrition.","Décrire le traitement des différents types de malnutrition aiguë."],"why":"Livret p. 94 : objectif général = « permettre à l'étudiant de la Licence 2 de prendre en charge la malnutrition chez l'enfant » ; aucune option ne le reprend (a, c, d sont des objectifs spécifiques, b n'est pas la formulation du cours)"},{"a":"179","c":0,"q":"La malnutrition est la conséquence directe de la pauvreté et de l'injustice. Ceci est une cause de type :","t":"qcm","nc":1,"o":["Immédiate","Sous-jacente","Fondamentale","Éducationnelle"],"why":"Le livret (p. 94) annonce les causes immédiates, sous-jacentes et fondamentales mais ne les détaille pas"},{"a":"180","c":0,"q":"La réduction du métabolisme d'environ 30% est une conséquence de la malnutrition sur :","t":"qcm","nc":1,"o":["Le plan socio-économique","Le plan éducationnel","La santé de l'enfant","L'environnement socio-sanitaire"],"why":"Réduction du métabolisme de 30% absente des sources"},{"a":"320","c":0,"q":"Concernant la différence entre vomissement et régurgitation :","t":"qcm","nc":1,"o":["La régurgitation est un phénomène actif avec effort musculaire.","Le vomissement est un phénomène passif.","Les régurgitations sont fréquentes chez le nourrisson de moins de 6 mois.","Les vomissements peuvent être précédés de nausées et de pâleur.","La régurgitation survient souvent en jet à distance du repas."],"why":"Le livre (p. 184, 186) définit seulement vomissement et régurgitation ; options C et D non tranchables"},{"a":"320","c":0,"q":"Lors du recueil de données, l'infirmier doit interroger les parents sur :","t":"qcm","nc":1,"o":["La date d'apparition et la fréquence des vomissements.","La couleur, l'odeur et la consistance du contenu vomi.","Les revenus mensuels des parents.","La prise de médicaments ou l'ingestion de toxiques.","Les antécédents de voyages ou de contage infectieux."],"why":"Anamnèse p. 186-187 : C (conditions socioéconomiques) ambigu, D et E absents"},{"a":"320","c":0,"q":"Les signes d'alerte devant un enfant vomissant sont :","t":"qcm","nc":1,"o":["Une fontanelle déprimée chez le nourrisson.","Un pli cutané persistant et une oligurie.","Des vomissements bilieux (verts) chez un nouveau-né.","Une somnolence ou une irritabilité excessive.","Une éruption cutanée localisée au visage."],"why":"Liste de signes d'alerte absente du chapitre vomissements"},{"a":"320","c":0,"q":"La Sténose Hypertrophique du Pylore se caractérise par :","t":"qcm","nc":1,"o":["Une prédominance féminine.","Un âge de survenue entre 2 et 8 semaines.","Des vomissements en jet, non bilieux.","Une cassure de la courbe de poids.","Un traitement médical de première intention par antiémétiques."],"why":"La SHP est seulement citée comme cause (p. 188), sans description"},{"a":"320","c":0,"q":"L'Invagination Intestinale Aiguë se manifeste par :","t":"qcm","nc":1,"o":["Des douleurs abdominales continues sans accalmie.","Des épisodes de pâleur et de cris chez le nourrisson.","Des selles hémorragiques précoces (gelée de groseille).","Un âge typique entre 3 et 36 mois.","Un diagnostic confirmé par l'échographie abdominale."],"why":"L'IIA est seulement citée comme cause (p. 188), sans description"},{"a":"320","c":0,"q":"Dans la prise en charge d'un enfant déshydraté par vomissements, la réhydratation orale (SRO) :","t":"qcm","nc":1,"o":["Doit être administrée en grande quantité d'un seul coup.","Est efficace si elle est donnée par petites cuillères à café répétées toutes les 5 à 10 minutes.","Est contre-indiquée en cas de gastro-entérite.","Peut être relayée par un lait artificiel normal après 24 heures si amélioration.","Doit être arrêtée si l'enfant vomit à nouveau ; il faut réessayer plus lentement."],"why":"Modalités de SRO chez l'enfant vomissant non décrites dans les sources"},{"a":"320","c":0,"q":"Les causes médicales (non chirurgicales) des vomissements chez l'enfant sont :","t":"qcm","nc":1,"o":["La méningite.","La pyélonéphrite.","L'intolérance au lactose post-gastro-entérite.","Le diabète de type 1 en acidocétose.","Le volvulus de la grêle."],"why":"Tableaux p. 188 : seule la méningite est citée ; B, C, D, E absents"},{"a":"320","c":0,"q":"Concernant les antiémétiques en pédiatrie :","t":"qcm","nc":1,"o":["Le métoclopramide peut être utilisé en toute sécurité à domicile.","L'ondansétron est particulièrement indiqué dans les vomissements post-chimiothérapie.","Les effets secondaires du métoclopramide incluent des troubles extrapyramidaux.","Ils doivent toujours être administrés sur prescription médicale.","La dompéridone est contre-indiquée chez l'enfant de moins de 12 kg."],"why":"Le livre (p. 190) ne cite que le syndrome extrapyramidal ; ondansétron, dompéridone < 12 kg et prescription absents"},{"a":"320","c":0,"q":"L'éducation des parents concernant la surveillance d'un enfant vomissant à domicile inclut :","t":"qcm","nc":1,"o":["Compter le nombre de couches mouillées par jour.","Surveiller l'apparition de signes de déshydratation (pli cutané, sécheresse buccale).","Donner de l'eau sucrée à volonté.","Consulter en urgence en cas de vomissements en jet.","Proposer des repas copieux pour compenser les pertes."],"why":"Éducation des parents de l'enfant vomissant non décrite dans les sources"},{"a":"320","c":0,"q":"Les vomissements bilieux (verts) chez un nouveau-né :","t":"qcm","nc":1,"o":["Sont souvent bénins et liés à une simple régurgitation.","Imposent une consultation chirurgicale en urgence.","Évoquent une occlusion intestinale haute (malrotation, volvulus).","Nécessitent la réalisation d'une aspiration gastrique par sonde.","Peuvent être traités par des antiémétiques en première intention."],"why":"Vomissements bilieux du nouveau-né non traités dans les sources"},{"a":"320","c":0,"q":"Les signes de déshydratation sévère chez le nourrisson sont :","t":"qcm","nc":1,"o":["Une fontanelle antérieure bombée.","Un pli cutané qui persiste (diminution de la turgescence).","Des muqueuses sèches et une absence de larmes.","Une polyurie (diurèse augmentée).","Une perte de poids supérieure à 5%."],"why":"Tableau p. 196 : fontanelle, diurèse et pourcentage de perte de poids absents"},{"a":"320","c":0,"q":"Dans le cadre du RGO (reflux gastro-œsophagien) du nourrisson, les mesures non médicamenteuses sont :","t":"qcm","nc":1,"o":["Mettre l'enfant en position allongée plate après chaque repas.","Fractionner les repas pour éviter les grosses distensions gastriques.","Surélever la tête du lit (position proclive) d'environ 30°.","Proposer un lait épaissi (anti-reflux) sur avis médical.","Administrer des antiémétiques forts au moindre reflux."],"why":"Le livre (p. 190-191) cite épaississement et fractionnement mais rien sur la position (A, C)"},{"a":"320","c":0,"q":"Le rôle infirmier lors de la préparation à une échographie abdominale pour suspicion de Sténose du Pylore consiste à :","t":"qcm","nc":1,"o":["Expliquer le déroulement de l'examen aux parents pour les rassurer.","Faire jeûner l'enfant selon les consignes.","Administrer un lavement avant l'examen.","Préparer l'enfant en position de décubitus ventral.","Surveiller l'état clinique de l'enfant pendant le jeûne."],"why":"Préparation à l'échographie absente des sources"},{"a":"320","c":0,"q":"Concernant la surveillance biologique d'un enfant vomissant, les examens à prescrire sont :","t":"qcm","nc":1,"o":["Un ionogramme sanguin (Na, K, Cl).","Une glycémie capillaire.","Un bilan hépatique complet systématique.","Des gaz du sang veineux.","Un bilan lipidique."],"why":"Le livre (p. 188) cite hémogramme, ionogramme et protidémie ; glycémie et gaz du sang non tranchables"},{"a":"320","c":0,"q":"Concernant l'allergie aux protéines du lait de vache (APLV) :","t":"qcm","nc":1,"o":["Elle peut se manifester par des vomissements et des régurgitations.","L'éviction du lait de vache est le seul traitement.","Les symptômes digestifs sont souvent associés à des signes cutanés (eczéma).","Elle est confirmée par un dosage des IgE spécifiques ou un test de provocation.","Elle impose l'utilisation de laits épaissis anti-reflux."],"why":"APLV non traitée dans les sources"},{"a":"320","c":0,"q":"Les mesures de confort post-vomissement que l'infirmier doit réaliser sont :","t":"qcm","nc":1,"o":["Rincer la bouche de l'enfant à l'eau ou au sérum physiologique.","Changement des vêtements et du linge souillés.","Remettre l'enfant immédiatement en position allongée pour le repos.","Surveillance de la coloration du contenu vomi.","Brossage des dents juste après le vomissement (pour les grands enfants)."],"why":"Mesures de confort post-vomissement absentes des sources"},{"a":"320","c":0,"q":"Les causes de vomissements chroniques récurrents chez l'enfant sont :","t":"qcm","nc":1,"o":["La maladie cœliaque.","Le syndrome des vomissements cycliques.","L'appendicite aiguë.","Le reflux gastro-œsophagien (RGO) sévère.","L'intoxication alimentaire aiguë."],"why":"Livre p.188 : causes des vomissements habituels = erreur diététique, RGO, SHP, vomissements psychogènes ; maladie cœliaque et syndrome des vomissements cycliques non cités, réponse complète non établie"},{"a":"320","c":0,"q":"Les indications de la réhydratation intraveineuse (IV) chez l'enfant vomissant sont :","t":"qcm","nc":1,"o":["Vomissements incoercibles ne permettant pas la voie orale.","Déshydratation sévère (> 10% de perte de poids).","Enfant joyeux, buvant bien, avec un pli cutané normal.","Troubles hydro-électrolytiques majeurs (déséquilibre ionique).","Simple gastro-entérite sans signe de déshydratation."],"why":"Livre p.199-201 : voie parentérale seulement pour les signes sévères de déshydratation (plan C) ; vomissements incoercibles, seuil >10 % et troubles ioniques non cités"},{"a":"320","c":0,"q":"Concernant les conseils de sortie et le suivi à domicile, l'infirmier doit expliquer aux parents :","t":"qcm","nc":1,"o":["Le protocole de réhydratation orale à suivre.","Les signes de retour nécessitant une consultation rapide.","Qu'il est normal que l'enfant ne s'alimente plus pendant 48h.","L'importance de la continuité des médicaments antiémétiques.","La date du rendez-vous de contrôle si prévu."],"why":"Conseils de sortie de l'enfant vomissant non détaillés dans les sources (livre p.190-191)"},{"a":"324","c":0,"q":"Entre 0 et 3 mois, quelle est une caractéristique du développement physique du bébé ?","t":"qcm","nc":1,"o":["Il peut étendre ses membres.","Il a le réflexe d'agrippement.","Il se tient assis sans soutien.","Il marche à quatre pattes."],"why":"Livre p.354 : quadriflexion et « réflexe de grasping » à 0-1 mois ; le terme « agrippement » et l'extension des membres ne figurent pas dans les sources"},{"a":"327","c":0,"q":"Quelle est une caractéristique du développement cognitif entre 4 et 6 mois ?","t":"qcm","nc":1,"o":["Il comprend des ordres complexes.","Il cherche un objet disparu.","Il lit des livres.","Il résout des problèmes mathématiques simples."],"why":"« Cherche un objet disparu » absent ; livre p.354 (6 mois) parle seulement de regarder où tombe le jouet (permanence de l'objet), OCR illisible"},{"a":"327","c":0,"q":"Comment le bébé de 4 à 6 mois s'exprime-t-il verbalement ?","t":"qcm","nc":1,"o":["En parlant couramment.","En utilisant des mots incompréhensibles (il jase).","En écrivant.","En chantant des chansons."],"why":"Sources : 6 mois = émet des syllabes / lallation ; « jaser, mots incompréhensibles » non cité"},{"a":"327","c":0,"q":"Entre 7 et 9 mois, quelle est une acquisition physique majeure ?","t":"qcm","nc":1,"o":["Il marche seul.","Il reste assis sans soutien.","Il court.","Il saute à pieds joints."],"why":"Sources : station assise à 6 mois (tenue assise en trépied, livre p.354) ; 7-9 mois = marche à 4 pattes ; la tenue assise sans soutien n'est pas placée à 7-9 mois"},{"a":"327","c":0,"q":"À quel âge le bébé commence-t-il à se déplacer à quatre pattes maladroitement ?","t":"qcm","nc":1,"o":["6 mois","7 mois","8 mois","9 mois"],"why":"Livret p.145 : marche à 4 pattes à 6-8 mois ; livre p.354 : à 9 mois ; âge précis non tranchable"},{"a":"327","c":0,"q":"Entre 7 et 9 mois, que comprend le bébé concernant son nom ?","t":"qcm","nc":1,"o":["Il ne le connaît pas encore.","Il connaît son nom et comprend le sens du « non ».","Il peut l'écrire.","Il l'ignore."],"why":"Livret p.145-146 : réagit à l'appel de son nom à 6 mois, comprend les interdits à 10-12 mois ; rien pour 7-9 mois"},{"a":"329","c":0,"q":"Entre 13 et 18 mois, quelle est une caractéristique du développement physique ?","t":"qcm","nc":1,"o":["L'enfant ne peut pas encore marcher seul.","L'enfant marche seul et monte les escaliers.","L'enfant court et grimpe.","L'enfant fait du vélo."],"why":"Livre p.355 : 15 mois marche seule, monte les escaliers à 4 pattes ; 18 mois court, monte en se tenant à la rampe ; B et C partiellement vraies, non tranchable"},{"a":"329","c":0,"q":"À quel âge l'enfant peut-il tenir une tasse et boire seul ?","t":"qcm","nc":1,"o":["12 mois","15 mois","18 mois","24 mois"],"why":"Livret : boit au verre à 10-12 mois (p.146) mais « peut boire seul » à 2 ans 1/2 (p.147) ; non tranchable"},{"a":"331","c":0,"q":"Selon le cours, à partir de quel âge un enfant doit-il faire l'objet de référence dans un service spécialisé s'il ne marche pas seul ?","t":"qcm","nc":1,"o":["Après 12 mois","Après 15 mois","Après 20 mois","Après 24 mois"],"why":"Âge de référence pour absence de marche non mentionné dans les sources"},{"a":"332","c":0,"q":"Le bilan prénatal est :","t":"qcm","nc":1,"o":["Un examen réalisé uniquement après l'accouchement","Un ensemble d'examens biologiques et d'imagerie réalisés pendant la grossesse pour surveiller la santé de la mère et du fœtus","Une consultation réservée au nouveau-né"],"why":"Bilan prénatal cité (livre p.14, p.47) mais jamais défini"},{"a":"332","c":0,"q":"La priorité de l'agent de santé en présence d'un nouveau-né normal porte principalement sur :","t":"qcm","nc":1,"o":["La vaccination et l'éducation","L'alimentation, l'éducation et la surveillance","L'hygiène, l'alimentation et la surveillance"],"why":"Livre p.14-16 : besoins prioritaires = alimentation, température, prévention des dangers ; rôle surtout préventif ; aucune option ne correspond"},{"a":"332","c":0,"q":"La première étape du développement de l'enfant c'est :","t":"qcm","nc":1,"o":["La nidation","L'œuf","La fécondation","L'embryon"],"why":"Étapes du développement prénatal absentes des sources"},{"a":"332","c":0,"q":"La période embryonnaire s'étend de :","t":"qcm","nc":1,"o":["J 0 à J 28 post natal","J 8 à J 90","J 90 à la naissance","La fécondation à J 8"],"why":"Période embryonnaire non traitée dans les sources"},{"a":"335","c":0,"q":"Les objectifs des soins essentiels sont :","t":"qcm","nc":1,"o":["Maintenir une température normale ;","Détecter les signes de danger ;","Aider la mère à mettre le nouveau-né au sein ;"],"why":"Cours p.5 : seuls l'intérêt (réduire la mortalité) et les objectifs pédagogiques sont donnés ; objectifs des soins essentiels non listés"},{"a":"337","c":0,"q":"Dans la détresse respiratoire, on a :","t":"qcm","nc":1,"o":["Plus le score est élevé, moins l'état de l'enfant est inquiétant ;","Coté de 0 à 3, de gravité croissante ;","Ce score est nul chez le nouveau-né normal."],"why":"Livre p.55 : score de Silverman de gravité croissante (3-4 modérée … 7-10 sévère) ; cotation par item et score nul du nouveau-né normal non lisibles/non établis"},{"a":"339","c":0,"q":"Le périmètre brachial permet d'évaluer l'état nutritionnel du nourrisson. Entre 1 et 2 ans il est de :","t":"qcm","nc":1,"o":["12 à 14 cm","14 à 16 cm","16 à 20 cm","11 à 13 cm"],"why":"Le cours (S p.62, 69) donne un PB normal de 12,5 à 16 cm entre 6 mois et 5 ans, sans valeur propre à 1-2 ans ; aucune option ne correspond"},{"a":"346","c":0,"q":"Le but de la mesure du périmètre crânien est :","t":"qcm","nc":1,"o":["D'apprécier le volume du crâne","De dépister un spina bifida","De dépister un omphalocèle","De dépister une macrocéphalie"],"why":"Le cours (S p.61) dit : apprécier le volume du CERVEAU et dépister une microcéphalie ou une hydrocéphalie ; aucune option ne reprend ces termes"},{"a":"347","c":0,"q":"À la naissance, la taille est de 50 cm, s'il est correctement nourri :","t":"qcm","nc":1,"o":["De 3 à 6 mois, il augmente de 0,5 cm par mois","De 0 à 3 mois, il augmente de 2 cm par mois","De 6 à 12 mois, il augmente de 0,25 cm par mois","De 12 mois à 4 ans, il augmente d'un 12 cm par mois"],"why":"Le cours (S p.68) donne 3 cm/mois (0-3 mois), 2 cm/mois (3-6), 1 à 1,5 cm/mois (6-12), 10 cm/an (12 mois-4 ans) : aucune option n'est conforme"},{"a":"347","c":0,"q":"Les gestes ci-dessous sont effectués pendant la minute d'or (0-1 minute) :","t":"qcm","nc":1,"o":["Sectionner le cordon ombilical, puis ventiler le bébé","Sécher le nouveau-né avec un linge propre et sec tout en le stimulant par des frictions","Demander de l'aide et améliorer la ventilation","Mesurer le rythme cardiaque par la palpation du moignon du cordon"],"why":"La « minute d'or » (stimulation par frictions, ventilation, palpation du cordon) n'est pas décrite dans les sources ; le cours (S p.7) cite seulement le séchage à 0-1 min, sans stimulation"},{"a":"347","c":0,"q":"Les éléments quantitatifs de la croissance de l'enfant sont :","t":"qcm","nc":1,"o":["Le poids, la taille, le périmètre crânien, le périmètre thoracique, le périmètre brachial","Le Z score, le poids, la taille et le périmètre crânien","La croissance des os, la taille, le périmètre thoracique","La fermeture de la fontanelle antérieure, la dentition"],"why":"Le cours (S p.58) cite poids, taille, PC et PB ; le périmètre thoracique ne figure dans aucune source, donc aucune option n'est exactement établie"},{"a":"349","c":0,"q":"Le périmètre crânien à la naissance est de 35 à 36 cm puis il augmente :","t":"qcm","nc":1,"o":["De 3 cm de 3 mois à 6 mois","De 1 cm de 6 mois à 12 mois","De 2 cm de la naissance à 3 mois","De 1 cm de 4 mois à 24 mois"],"why":"Le cours (S p.68) donne 2 cm/mois (0-3 mois), 1 cm/mois (3-6), 0,5 cm/mois (6-12) ; options non tranchables (A juste en total sur la période, C juste par mois)"},{"a":"354","c":0,"q":"Le but de la mesure du périmètre crânien est :","t":"qcm","nc":1,"o":["De dépister une anencéphalie","D'apprécier le volume du crâne","De dépister un spina bifida"],"why":"Le cours (S p.61) dit : apprécier le volume du CERVEAU et dépister une microcéphalie ou une hydrocéphalie ; aucune option ne reprend ces termes"}]};
